/**
 * Writes `fixtures/package/v8/renovation.buildbox`, its `project.json` and its asset (#69 §1).
 *
 * Run it with the flag set — `VITE_FF_RENOVATION=true npx vite-node scripts/make-v8-package-fixture.ts`
 * — because the file is a preview package: the schema version it stamps is the flagged one, and
 * `preview: true` is what makes a production build refuse it. Like every golden file it is committed
 * bytes, never regenerated by a test; `fixtures.test.ts` proves these bytes still round-trip.
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { canonicalJsonBytes } from '../src/lib'
import { encodeProject } from '../src/package/encode'
import { FIXTURE_BUILD, FIXTURE_PLAN_IMAGE_HASH, renovationFixtureProject } from '../src/package/testing'

const assetBytes = readFileSync(join('fixtures', 'package', 'v7', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
const assetSource = async (): Promise<{ bytes: Uint8Array; mediaType: string }> => ({
  bytes: new Uint8Array(assetBytes),
  mediaType: 'image/png',
})

const project = renovationFixtureProject()
const bytes = await encodeProject(project, assetSource, { ...FIXTURE_BUILD, preview: true })

const dir = join('fixtures', 'package', 'v8')
mkdirSync(join(dir, 'assets'), { recursive: true })
writeFileSync(join(dir, 'renovation.buildbox'), bytes)
writeFileSync(join(dir, 'project.json'), `${new TextDecoder().decode(canonicalJsonBytes(project))}\n`)
copyFileSync(join('fixtures', 'package', 'v7', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`), join(dir, 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
console.info(`wrote ${join(dir, 'renovation.buildbox')}: ${String(bytes.length)} bytes`)
